'use client';

import * as React from 'react';
import { motion, type Variants } from 'motion/react';

import {
  getVariants,
  useAnimateIconContext,
  IconWrapper,
  type IconProps,
} from '@animate-ui/react/icons';

type RotateCcwProps = IconProps<keyof typeof animations>;

const animations = {
  default: {
    group: {
      initial: {
        rotate: 0,
        scale: 1,
        transition: { type: 'spring', stiffness: 150, damping: 25 },
      },
      animate: {
        rotate: -45,
        scale: 0.85,
        transition: { type: 'spring', stiffness: 150, damping: 25 },
      },
    },
    path1: {},
    path2: {},
  } satisfies Record<string, Variants>,
  rotate: {
    group: {
      initial: {
        rotate: 0,
        scale: 1,
        transition: { type: 'spring', stiffness: 170, damping: 26 },
      },
      animate: {
        rotate: -360,
        scale: [1, 0.8, 0.8, 1],
        transition: {
          rotate: { type: 'spring', stiffness: 170, damping: 26, delay: 0.1 },
          scale: {
            duration: 1.4,
            ease: 'easeInOut',
            times: [0, 0.07, 0.85, 1],
          },
        },
      },
    },
    path1: {},
    path2: {},
  } satisfies Record<string, Variants>,
} as const;

function IconComponent({ size, ...props }: RotateCcwProps) {
  const { controls } = useAnimateIconContext();
  const variants = getVariants(animations);

  return (
    <motion.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      variants={variants.group}
      initial="initial"
      animate={controls}
      {...props}
    >
      <motion.g variants={variants.group} initial="initial" animate={controls}>
        <path
          d="M3.99219 2V5.13219C3.99219 5.42605 4.35943 5.55908 4.54746 5.33333C6.37759 3.2875 9.03718 2 11.9973 2C17.5173 2 21.9922 6.47715 21.9922 12C21.9922 15.9582 19.6937 19.3793 16.3592 21"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
        <path
          d="M11.7269 22.0003C12.1938 22.0003 12.6533 21.9691 13.1033 21.9086"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
        <path
          d="M2.25756 8.66699C2.14516 9.06418 2.05696 9.4656 1.99219 9.86925"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
        <path
          d="M2.02676 13.5383C2.09706 13.9384 2.18863 14.3345 2.30071 14.7247"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
        <path
          d="M3.8251 17.9966C4.06343 18.35 4.32178 18.6902 4.59928 19.0149"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
        <path
          d="M7.42075 21.361C7.77446 21.5634 8.14261 21.7466 8.52446 21.9086"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </motion.g>
    </motion.svg>
  );
}

function RotateCcw(props: RotateCcwProps) {
  return <IconWrapper icon={IconComponent} {...props} />;
}

export {
  animations,
  RotateCcw,
  RotateCcw as RotateCcwIcon,
  type RotateCcwProps,
  type RotateCcwProps as RotateCcwIconProps,
};
